function formatMarkdown(text) {
  if (!text) return '';
  // Escapar HTML básico
  let escaped = text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

  // Reemplazar enlaces Markdown [texto](url)
  escaped = escaped.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer" class="text-amber-400 font-semibold underline hover:text-amber-300">$1</a>');

  // Negritas **texto**
  escaped = escaped.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

  // Viñetas simples
  escaped = escaped.replace(/^\s*-\s+(.+)$/gm, '• $1');

  return escaped;
}

